```vue src/components/kanban/KanbanContainer.vue
<script setup>
import ChatViewVue from '../../views/ChatView.vue'
import KanbanList from './KanbanList.vue'
import ChatHistoryVue from './ChatHistory.vue'
import Kanban from './Kanban.vue'
import NewEditBoardModal from './NewEditBoardModal.vue'
</script>

<template>
  <div class="w-full h-full flex flex-col gap-1">

    <!-- Chat History -->
    <ChatHistoryVue
      :projects="[$project, ...$projects.childProjects]"
      v-if="showHistory" />

    <!-- Kanban list -->
    <KanbanList
      :boards="boards"
      @select="selectBoard"
      @new="showNewBoardModal"
      @bookmark="toggleBookmark"
      @delete="onDeleteBoard"
      v-if="showKanbanList"
    />

    <!-- Active chat view -->
    <ChatViewVue
      class="h-full rounded-lg my-2"
      @chats="onChatEditDone"
      @sub-task="createSubTask"
      @sub-tasks="createSubTasks"
      @chat="setActiveChat($event)"
      @change-column="moveChatsToColumn"
      :kanban="activeBoard"
      :chat="$projects.activeChat"
      v-if="showChatView"
    />

    <!-- Kanban board view -->
    <Kanban
      @edit-board="onEditBoard"
      v-if="showKanban"
    />

    <!-- New/Edit Board modal -->
    <modal close="true" @close="editBoard = null" v-if="editBoard">
      <NewEditBoardModal :board="editBoard" :boards="boards" @save="onSaveBoard" />
    </modal>

    <!-- Add Board modal -->
    <modal close="true" @close="showBoardModal = false" v-if="showBoardModal">
      <h2 class="font-bold text-3xl">Add New Board</h2>
      <div class="collapse bg-contain" :style="`background-image:url('${newBoardBackground}')`">
        <div class="collapse-content">
          <div class="text-xl text-info font-bold" v-if="activeBoard">Parent {{ activeBoard }}</div>
          <input type="text" v-model="newBoardName" placeholder="Enter board name" class="input input-bordered w-full mt-2" />
          <input type="text" v-model="newBoardDescription" placeholder="Enter board description" class="input input-bordered w-full mt-2" />
          <input type="text" v-model="newBoardBackground" placeholder="Enter board background image" class="input input-bordered w-full mt-2" />
          <select v-model="newBoardParent" class="select select-bordered w-full mt-2">
            <option value="">-- none --</option>
            <option v-for="board in boards" :key="board.title" :value="board.title">{{ board.title }}</option>
          </select>
        </div>
      </div>
      <div class="modal-action flex gap-2">
        <div class="grow"></div>
        <button class="btn" @click="addNewBoard" :disabled="!newBoardName">Save</button>
      </div>
    </modal>
  </div>
</template>

<script>
import { v4 as uuidv4 } from 'uuid'

export default {
  data() {
    return {
      showHistory: false,
      editBoard: null,
      showBoardModal: false,
      newBoardName: '',
      newBoardDescription: '',
      newBoardBackground: '',
      newBoardParent: null
    }
  },
  created() {
    this.projectChanged()
  },
  computed: {
    kanban() {
      return this.$projects.kanban || { boards: {} }
    },
    boards() {
      const keys = Object.keys(this.kanban.boards || {})
      return keys
        .map(title => ({ title, ...this.kanban.boards[title] }))
        .filter(b => !this.selectedBoard || b.parent_id === this.selectedBoard)
    },
    selectedBoard() {
      return this.$projects.activeBoard
    },
    activeBoard() {
      return this.kanban?.boards[this.$projects.activeBoard]
        ? this.$projects.activeBoard
        : null
    },
    showChatView() {
      return !this.showHistory && !!this.$projects.activeChat
    },
    showKanban() {
      return !this.showHistory && !this.showChatView && !!this.activeBoard
    },
    showKanbanList() {
      return !this.showHistory && !this.showChatView && !this.showKanban
    }
  },
  watch: {
    project() {
      this.projectChanged()
    }
  },
  methods: {
    async projectChanged() {
      await this.$projects.loadKanban()
      this.selectBoard()
    },

    async selectBoard(board) {
      await this.$projects.setActiveBoard(board)
    },

    onEditBoard(board) {
      this.editBoard = board
    },

    onSaveBoard() {
      this.editBoard = null
    },

    // Open modal for creating a new board
    showNewBoardModal() {
      this.newBoardName = ''
      this.newBoardDescription = ''
      this.newBoardBackground = ''
      this.newBoardParent = this.activeBoard || null
      this.showBoardModal = true
    },

    async addNewBoard() {
      const name = this.newBoardName?.trim()
      if (!name || this.kanban.boards[name]) return

      this.kanban.boards[name] = {
        title: name,
        description: this.newBoardDescription?.trim(),
        background: this.newBoardBackground?.trim(),
        parent_id: this.newBoardParent || null,
        columns: [],
        id: name
      }
      await this.$projects.saveKanban()
      this.showBoardModal = false
    },

    toggleBookmark({ title } = {}) {
      const boardTitle = title || this.activeBoard
      const board = this.kanban.boards[boardTitle]
      if (!board) return
      board.bookmark = !board.bookmark
      this.$projects.saveKanban()
    },

    async onDeleteBoard(boardTitle) {
      if (!boardTitle || !this.kanban.boards[boardTitle]) return
      delete this.kanban.boards[boardTitle]
      await this.$projects.saveKanban()
    },

    // Close chat view and return to board
    onChatEditDone() {
      this.$projects.setActiveChat()
    },

    async setActiveChat(chat) {
      chat && await this.$projects.reloadChat(chat)
      this.$projects.setActiveChat(chat)
    },

    async createSubTask({ parent, name, mode, description, project_id, parent_id, message_id, file_list, activateChat, child_index, column, profiles }) {
      const chat = await this.$projects.createNewChat({
        id: uuidv4(),
        board: parent.board,
        name,
        mode,
        profiles,
        column: column || parent.column,
        parent_id: parent_id || parent.id,
        message_id,
        project_id: project_id || parent.project_id,
        messages: description ? [{ role: 'user', content: description }] : [],
        file_list,
        child_index
      })
      if (activateChat !== false) await this.setActiveChat(chat)
      await this.$projects.saveChat(chat)
      if (description) this.$storex.projects.chatWihProject(chat)
    },

    async createSubTasks(event) {
      this.$projects.createSubtasks(event)
    },

    async moveChatsToColumn({ chats, column }) {
      await Promise.all(
        chats.map(chat => this.$projects.saveChatInfo({ ...chat, column }))
      )
    }
  }
}
</script>
